/* aesthetic chrome v2.18.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-line: #e9e9e9;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-line-dark: #262626;
  --ae-space-4: 1em;
  --ae-space-5: 1.5em;
  --ae-space-6: 2em;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
    --ae-line: var(--ae-line-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

:root.dark,
:root[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
  --ae-line: var(--ae-line-dark);
}

.ae-chrome {
font-size: 13px;
  color: var(--ae-ink-muted);
}

.ae-chrome a {
color: var(--ae-ink-muted);
  text-decoration: none;
}

.ae-chrome a:hover {
color: var(--ae-ink);
}

.ae-foot {
font-size: 13px;
  color: var(--ae-ink-muted);
  border-top: 1px solid var(--ae-line);
  padding-top: var(--ae-space-4);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--ae-space-4) var(--ae-space-6);
  flex-wrap: wrap;
}

.ae-foot a {
color: var(--ae-ink-muted);
  text-decoration: none;
}

.ae-foot a:hover {
color: var(--ae-ink);
}

.ae-foot-links {
display: inline-flex;
  gap: var(--ae-space-5);
  align-items: center;
}
